589	    fn next(&mut self) -> Option<Self::Item> {
590	        let mut descend = false;
591	
592	        if self.stack.is_empty() {
593	            self.stack
594	                .push(StackEntry {
595	                    tree: self.tree,
596	                    index: 0,
597	                    position: (),
598	                })
599	                .unwrap_oob();
600	            descend = true;
601	        }
602	
603	        while let Some(entry) = self.stack.last_mut() {
604	            let new_subtree = {
605	                match entry.tree.0.as_ref() {
606	                    Node::Internal { child_trees, .. } => {
607	                        if !descend {
608	                            entry.index += 1;
609	                        }
610	                        child_trees.get(entry.index())
611	                    }
612	                    Node::Leaf { items, .. } => {
613	                        if !descend {
614	                            entry.index += 1;
615	                        }
616	
617	                        if let Some(next_item) = items.get(entry.index()) {
618	                            return Some(next_item);
619	                        } else {
620	                            None
621	                        }
622	                    }
623	                }
624	            };
625	
626	            if let Some(subtree) = new_subtree {
627	                descend = true;
628	                self.stack
629	                    .push(StackEntry {
630	                        tree: subtree,
631	                        index: 0,
632	                        position: (),
633	                    })
634	                    .unwrap_oob();
635	            } else {
636	                descend = false;
637	                self.stack.pop();
638	            }
639	        }
640	
641	        None
642	    }
